pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }
    function testFuzz_property(uint256 amount, uint256 ts, address actor) public {
        vm.assume(actor != address(c));
        vm.assume(amount != 10 ether); // force the requires to fail (admissible: any bad-value call)
        vm.warp(bound(ts, 1, type(uint256).max / 2));
        uint256 before = c.pastBlockTime();
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        (bool success,) = address(c).call{value: amount}("");
        ok = success;
        assertTrue(!ok, "call should revert");
        // general rule: reverting calls must not change pastBlockTime
        assertTrue(c.pastBlockTime() == before, "pastBlockTime must be unchanged after a reverted call");
    }
}

