pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 k, uint256 ts, address actor) public {
        k = bound(k, 1, 10_000);
        ts = bound(ts, 1, 1_000_000_000);
        uint256 blk = k * 105 + 7; // divisible by 7, never by 15
        vm.roll(blk);
        if (blk >= 2) vm.warp(ts);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        c.fallback{value: 10 ether}();
        // On a block divisible by 7 but not 15, C pays nothing: balance must stay at 20 ether.
        assertTrue(address(c).balance == 20 ether);
    }
}

