        vm.assume(ts > 0);
        vm.assume(actor != address(0) && actor != address(c));
        // land on an admissible block: any block number divisible by 15
        vm.roll(k * 15);
        // timestamp strictly greater than pastBlockTime (admissible domain)
        vm.warp(ts);

        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        // General rule: after any admissible fallback call on a block divisible by 15,
        // the contract transfers its whole balance to the caller.
        assertTrue(address(c).balance == 0);
    }
}

