pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNum, uint256 ts, address actor) public {
        // keep timestamps in a sane, strictly-positive domain (avoids any overflow corner cases)
        ts = bound(ts, 1, 1e18);
        blockNum = bound(blockNum, 0, 1e18);
        vm.assume(actor != address(0) && actor != address(c));

        vm.roll(blockNum);
        vm.warp(ts);

        uint256 amount = 10 ether;
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: amount}("");

        if (ok) {
            // The rule: the contract pays out (balance 0) if and only if block.number % 15 == 0.
            bool empty = address(c).balance == 0;
            assertTrue((blockNum % 15 == 0) == empty);
        } else {
            // If the entry reverted (e.g. timestamp not strictly increasing), nothing is paid out.
            assertTrue(address(c).balance == 20 ether);
        }
    }
}

