import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNumber, uint256 ts, address actor) public {
        vm.assume(blockNumber % 15 == 0 && blockNumber > 0);
        vm.assume(ts > 0);
        vm.assume(actor != address(0) && actor != address(c));
        vm.roll(blockNumber);
        vm.warp(ts);
        vm.deal(actor, 10 ether);
        uint256 cBefore = address(c).balance;
        uint256 actorBefore = actor.balance;
        vm.prank(actor);
        c.fallback{value: 10 ether}();
        // Rule: on a payout block, the caller receives exactly c's entire prior balance.
        assertTrue(actor.balance == actorBefore + cBefore && address(c).balance == 0);
    }
}
